8	/*
9	 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-attributes.jsx
10	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
11	 * plan step 2.1). Zero functional diff beyond the TypeScript annotations below, the
12	 * `useItemVariant` import path rewrite (see next paragraph), and a temporary `[overrides]`
13	 * console.log marker (verified live, then removed). The `<Stack spacing={1.5} flex={1} {...props}>` defaults-then-spread prop
14	 * order is preserved exactly, unchanged from base.
15	 *
16	 * The base file imports `useItemVariant` from the SFCC package path
17	 * (`@salesforce/retail-react-app/app/components/item-variant`) — inconsistent with its own three
18	 * siblings (item-image/item-name/item-price), which all already import it via the relative `'.'`.
19	 * Since `item-variant/index.tsx` is itself being overridden in this same commit,
20	 * this import is rewritten to match its siblings (`'.'`) per
21	 * .claude/rules/overrideStyling.md's "Importing an already-overridden component from a new
22	 * component" — a base-path import here would silently exercise the base `useItemVariant`/context
23	 * in Storybook and Vitest instead of this override.
24	 *
25	 * `useCurrentBasket` (from the SFCC hooks path) and the `useCurrency`/`app/hooks` barrel are not
26	 * overridden anywhere in this repo (verified by directory listing at time of writing — no
27	 * overrides/app/hooks/use-current-basket.ts, no overrides/app/hooks/index.ts), so both stay on
28	 * the base `@salesforce/retail-react-app/...` path.
29	 *
30	 * SFCC-270 (plan step 2.2): adds `combineAttributeValues`, used by product-item/index.tsx to
31	 * render the Figma cart-item spec's colour+size string ("Lilac Sand, One size") as a single
32	 * combined <Text>, instead of this file's existing per-key behaviour (one <Text> per
33	 * variation-value key, with or without its label per `hideAttributeLabels`) — a genuinely
34	 * different rendering shape, not just `hideAttributeLabels` with the label omitted, since that
35	 * flag still produces one <Text> per key. Defaults to `false`, so the existing per-key
36	 * behaviour (and every other branch in this file — bonus label, quantity, bundles, promotions)
37	 * is unchanged for any caller that doesn't pass it.
38	 */
39	import React from 'react';
40	import { useIntl, FormattedMessage, FormattedNumber } from 'react-intl';
41	import { Flex, Stack, Text, Box, useMultiStyleConfig } from '@salesforce/retail-react-app/app/components/shared/ui';
42	import { useItemVariant } from '.';
43	import PromoPopover from '@salesforce/retail-react-app/app/components/promo-popover';
44	import { useCurrency } from '@salesforce/retail-react-app/app/hooks';
45	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
46	import { usePromotions, useProducts, useProduct } from '@salesforce/commerce-sdk-react';
47	import { getDisplayVariationValues } from '@salesforce/retail-react-app/app/utils/product-utils';
48	// Recipe key — single source in item-variant.css.ts (SFCC-270 round 2 rework), no longer
49	// redeclared per file.
50	import { ZIMM_CART_ITEM_VARIANT_RECIPE } from './item-variant.css';
51	
52	// See index.tsx's own note on why this is `any` rather than a structural type.
53	type SfccVariant = any;
54	
55	type ItemAttributesProps = {
56	  includeQuantity?: boolean;
57	  currency?: string;
58	  excludeBonusLabel?: boolean;
59	  hideAttributeLabels?: boolean;
60	  /** See this file's own SFCC-270 docblock note above. */
61	  combineAttributeValues?: boolean;
62	} & Record<string, any>;
63	
64	/**
65	 * In the context of a cart product item variant, this component renders a styled
66	 * list of the selected variation values as well as any promos (w/ info popover).
67	 */
68	const ItemAttributes = ({
69	  includeQuantity,
70	  currency,
71	  excludeBonusLabel,
72	  hideAttributeLabels = false,
73	  combineAttributeValues = false,
74	  ...props
75	}: ItemAttributesProps) => {
76	  const variant: SfccVariant = useItemVariant();
77	  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});
78	  const { data: basket } = useCurrentBasket();
79	  const { currency: activeCurrency } = useCurrency();
80	  const promotionIds = variant.priceAdjustments?.map((adj: SfccVariant) => adj.promotionId) ?? [];
81	  const intl = useIntl();
82	
83	  const displayBonusProductLabel = !excludeBonusLabel && variant?.bonusProductLineItem;
84	
85	  // Fetch all the promotions given by price adjustments. We display this info in
86	  // the promotion info popover when applicable.
87	  const { data: res } = usePromotions(
88	    {
89	      parameters: {
90	        ids: promotionIds.join(','),
91	      },
92	    },
93	    {
94	      enabled: promotionIds.length > 0,
95	    },
96	  );
97	  const promos = res?.data || [];
98	  const variationValues = getDisplayVariationValues(variant?.variationAttributes, variant?.variationValues);
99	
100	  // get variant info for bundled products in cart page and order history page
101	  const productBundleIds = variant?.bundledProductItems?.map(({ productId }: SfccVariant) => productId).join(',') ?? '';
102	  const { data: productBundleVariantData, isLoading: bundleVariantIsLoading } = useProducts(
103	    {
104	      parameters: {
105	        ids: productBundleIds,
106	        allImages: false,
107	      },
108	    },
109	    {
110	      enabled: Boolean(variant?.type?.bundle && productBundleIds),
111	      select: (result: SfccVariant) => {
112	        // formats response so we can easily display child quantity/variant selection
113	        return result?.data?.map((item: SfccVariant) => {
114	          const quantity = variant?.bundledProductItems.find(
115	            (childProduct: SfccVariant) => childProduct.productId === item.id,
116	          )?.quantity;
117	          return {
118	            ...item,
119	            quantity,
120	            variationValues: getDisplayVariationValues(item?.variationAttributes, item?.variationValues),
121	          };
122	        });
123	      },
124	    },
125	  );
126	
127	  // get bundle product data for wishlist page
128	  const { data: productBundleData, isLoading: productBundleIsLoading } = useProduct(
129	    {
130	      parameters: {
131	        id: variant?.id,
132	        allImages: false,
133	      },
134	    },
135	    {
136	      enabled: Boolean(variant?.type?.bundle && !productBundleIds),
137	    },
138	  );
139	
140	  return (
141	    <Stack spacing={1.5} flex={1} {...props}>
142	      {displayBonusProductLabel && (
143	        <Text lineHeight={1} color="black.600" fontSize="sm">
144	          <FormattedMessage defaultMessage="Bonus Product" id="item_attributes.label.bonus_product" />
145	        </Text>
146	      )}
147	
148	      {variationValues && combineAttributeValues && (
149	        <Text sx={styles.colourSize}>{Object.values(variationValues).join(', ')}</Text>
150	      )}
151	
152	      {variationValues &&
153	        !combineAttributeValues &&
154	        Object.keys(variationValues).map((key) => (
155	          <Text lineHeight={1} color="gray.700" fontSize="sm" key={`${key}: ${variationValues[key]}`}>
156	            {hideAttributeLabels ? variationValues[key] : `${key}: ${variationValues[key]}`}
157	          </Text>
158	        ))}
159	
160	      {includeQuantity && (
161	        <Text lineHeight={1} color="gray.700" fontSize="sm">
162	          <FormattedMessage
163	            defaultMessage="Quantity: {quantity}"
164	            values={{ quantity: variant.quantity }}
165	            id="item_attributes.label.quantity"
166	          />
167	        </Text>
168	      )}
169	
170	      {!productBundleIsLoading && productBundleData && !productBundleVariantData && (
171	        <Box>
172	          {/* Deviation from the base file (same labelled-comment convention as
173	                        product-view/index.tsx:659-661/1019-1022): added `?.` before `.map` —
174	                        `bundledProducts` is itself optional on the SDK's real Product type even
175	                        once `productBundleData` is truthy, which strict null checks catches and
176	                        the base file's plain JS did not need to guard against. This is a real,
177	                        narrow behaviour difference from base, not a pure typing satisfier: base
178	                        would throw here if `bundledProducts` were ever undefined on an otherwise
179	                        truthy `productBundleData`; this renders nothing instead. Directionally
180	                        safer (crash -> silent no-render), so left as-is rather than reverted to
181	                        match base's crash-on-that-shape behaviour exactly. */}
182	          {productBundleData?.bundledProducts?.map(({ product, quantity }: SfccVariant) => (
183	            <Box marginTop={2} key={product.id}>
184	              <Text fontSize="sm" color="gray.700" as="b">
185	                {product?.name}
186	              </Text>
187	              <Text fontSize="sm" color="gray.700">
188	                {intl.formatMessage({
189	                  defaultMessage: 'Qty',
190	                  id: 'add_to_cart_modal.label.quantity',
191	                })}
192	                : {quantity}
193	              </Text>
194	            </Box>
195	          ))}
196	        </Box>
197	      )}
198	
199	      {!bundleVariantIsLoading && productBundleVariantData && (
200	        <Box>
201	          <Text fontSize={15} marginTop={3} fontWeight={500}>
202	            {intl.formatMessage({
203	              defaultMessage: 'Selected Options',
204	              id: 'item_attributes.label.selected_options',
205	            })}
206	            :
207	          </Text>
208	          {productBundleVariantData?.map(({ variationValues, name: productName, quantity, id }: SfccVariant) => {
209	            return (
210	              <Box key={id} marginTop={2}>
211	                <Text fontSize="sm" color="gray.700" as="b">
212	                  {productName}
213	                </Text>
214	                <Text fontSize="sm" color="gray.700">
215	                  {intl.formatMessage({
216	                    defaultMessage: 'Qty',
217	                    id: 'add_to_cart_modal.label.quantity',
218	                  })}
219	                  : {quantity}
220	                </Text>
221	                {Object.keys(variationValues).map((key) => {
222	                  const selectedVariant = `${key}: ${variationValues[key]}`;
223	                  return (
224	                    <Text fontSize="sm" color="gray.700" key={selectedVariant}>
225	                      {selectedVariant}
226	                    </Text>
227	                  );
228	                })}
229	              </Box>
230	            );
231	          })}
232	        </Box>
233	      )}
234	
235	      {variant.priceAdjustments?.length > 0 && (
236	        <Flex alignItems="center">
237	          <Text lineHeight={1} color="gray.700" fontSize="sm">
238	            <FormattedMessage defaultMessage="Promotions" id="item_attributes.label.promotions" />
239	            {': '}
240	            <Text as="span" color="green.700">
241	              <FormattedNumber
242	                style="currency"
243	                currency={currency || basket?.currency || activeCurrency}
244	                value={variant.priceAdjustments.reduce((acc: number, adj: SfccVariant) => acc + (adj.price ?? 0), 0)}
245	              />
246	            </Text>
247	          </Text>
248	          <PromoPopover ml={2}>
249	            <Stack>
250	              {promos?.map((promo: SfccVariant) => (
251	                <Text key={promo?.id} fontSize="sm">
252	                  {promo?.calloutMsg}
253	                </Text>
254	              ))}
255	            </Stack>
256	          </PromoPopover>
257	        </Flex>
258	      )}
259	    </Stack>
260	  );
261	};
262	
263	export default ItemAttributes;
